UPDATE Booking SET customerDetails = '{"name":"Markus Lenhart","paid":false,"email":"markus.lenhart@gmx.de","source":"migrated_from_matukio","language":"en-GB","checkedIn":false,"oldBookingId":6714,"salutation":"Herr","fullName":"Markus Lenhart","street":"Theodor-Neubauer-Straße 60","zip":"04318","city":"Leipzig","phone":"016097709046","sizeWeight":"95","birthDate":"14.12.1989"}', remarks = 'Hallo zusammen,

